type ComponentIconProps = { className?: string };

function makeIcon(data: IconData) {
  return function Icon({ className = "h-[18px] w-auto" }: ComponentIconProps) {
    return (
      <svg viewBox={data.viewBox} fill={data.color} aria-hidden="true" className={className}>
        {data.paths.map((p, i) => (
          <path key={i} d={p.d} fillRule={p.fillRule} clipRule={p.clipRule} />
        ))}
      </svg>
    );
  };
}

